rowObjects.data:
{{
  (() => {
    // 1. Parameter aus dem .run()-Aufruf holen
    const active = String(appsmith.store.activeVentil || "").trim();
    const stammdatenArray = Stammdaten.data || [];

    // Status bestimmen (true für "Nicht belegt", "" für gelöscht/programmiert)
    const neuerStatus = this.params && this.params.neuerStatus !== undefined 
      ? this.params.neuerStatus 
      : "";

    // Target Index aus params lesen oder über das aktive Ventil suchen
    let targetIdx = this.params && this.params.targetIndex !== undefined 
      ? Number(this.params.targetIndex) 
      : -1;

    if (targetIdx === -1) {
      targetIdx = stammdatenArray.findIndex(r => 
        String(r.Ventil_Links || "").trim() === active || 
        String(r.Ventil_Rechts || "").trim() === active
      );
    }

    // Abbrechen, falls nichts gefunden wurde
    if (targetIdx === -1 || !stammdatenArray[targetIdx]) {
      return {};
    }

    const foundRow = stammdatenArray[targetIdx];
    const isLinkesVentil = String(foundRow.Ventil_Links || "").trim() === active;

    return {
      "rowIndex": targetIdx,
      "Status_Leer_Links": isLinkesVentil ? neuerStatus : (foundRow.Status_Leer_Links || ""),
      "Status_Leer_Rechts": !isLinkesVentil ? neuerStatus : (foundRow.Status_Leer_Rechts || "")
    };
  })()
}}
